from acmesdk.billing import settle_discount
result = settle_discount(12)
result = {'value': result[0]}
assert result == {'value': 6.0}
print('Success')

from acmesdk.scheduler import compose_window
result = compose_window(['tango', 'flint', 'pixel', 'alpha', 'flint'])
result = {'value': result}
assert result == {'value': 'TANGO FLINT PIXEL ALPHA FLINT'}
print('Success')

from acmesdk.search import top_query
keys = ['id', 'name', 'owner']
record = {'id': 27, 'name': 'echo', 'tier': 'b'}
result = top_query(keys, record)
for k in keys:
    if k not in result:
        result[k] = None
assert result == {'id': 27, 'name': 'echo', 'owner': None}
print('Success')

from acmesdk.auth import extract_nonce
raw = extract_nonce(entries=[{'id': 0, 'score': 3}, {'id': 1, 'score': 1}, {'id': 2, 'score': 35}, {'id': 3, 'score': 56}, {'id': 4, 'score': 25}], key='score', credential='sess-9')
result = {'value': [item['score'] for item in raw['value']]}
assert result == {'value': [56, 35, 25]}
print('Success')

from acmesdk.storage import collect_chunk
result = collect_chunk({'id': 1, 'name': 'nova', 'tier': 'a'}, ['id', 'name', 'owner'])
result = {'value': result}
assert result == {'value': {'id': 1, 'name': 'nova', 'owner': None}}
print('Success')

